const storageKey = 'workmate.locale';
const locale = ref<Locale>('zh-CN');

function applyLocale(value: Locale) {
  document.documentElement.lang = value;
}
applyLocale(locale.value);

export function useI18n() {
  const setLocale = (value: Locale) => {
    locale.value = value;
    void writeStored(storageKey, value);
    applyLocale(value);
  };
  const t = (key: string, values?: Record<string, string | number>) => Object.entries(values ?? {}).reduce((text, [name, value]) => text.replaceAll(`{${name}}`, String(value)), messages[locale.value][key] ?? key);
  const loadLocale = async () => { const saved = await readStored(storageKey); if (localeOptions.includes(saved as Locale)) { locale.value = saved as Locale; applyLocale(locale.value); } };
  return { locale, setLocale, t, isChinese: computed(() => locale.value === 'zh-CN'), loadLocale };
}
